struct Authenticator {
  virtual std::optional<Principal> verify(std::string_view cred) = 0;
  virtual ~Authenticator() = default;
};
bool enforce(const Request& req, Response& res, Authenticator& auth, Principal& out) {
  if (is_public(req.path())) return true;                     // explicit public surface
  if (auto p = auth.verify(bearer(req))) { out = *p; return true; }  // delegated
  res = challenge_401(req);                                   // single challenge site
  return false;
}

