struct AuthMiddleware {
  struct context { std::optional<Principal> principal; };
  TokenVerifier* verify = nullptr;                        // injected mechanism
  void before_handle(crow::request& req, crow::response& res, context& ctx) {
    if (req.url == "/health") return;                     // explicit public route
    auto p = verify->check(req.get_header_value("Authorization"));
    if (!p) { res.code = 401; res.end(); return; }        // challenge ends the chain
    ctx.principal = *p;                                   // request-local principal
  }
  void after_handle(crow::request&, crow::response&, context&) {}
};
crow::App<AuthMiddleware> app;                            // middleware applied app-wide
